import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { FiMenu, FiX, FiSun, FiMoon, FiUser, FiLogOut, FiBook, FiHome, FiInfo, FiMessageSquare } from 'react-icons/fi';
import { motion, AnimatePresence, useScroll, useSpring, useTransform } from 'framer-motion';
import { Button } from '../ui';

const Navbar = () => {
  const { currentUser, isAuthenticated, logout, isAdmin, isTeacher, isStudent } = useAuth();
  const { darkMode, toggleDarkMode } = useTheme();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  // Scroll progress for the progress bar
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  // Color transform for scroll progress bar based on scroll position
  const progressColor = useTransform(
    scrollYProgress,
    [0, 0.5, 1],
    ["#0EA5E9", "#0284C7", "#0369A1"]
  );

  // Check if the current path matches the link
  const isActive = (path) => {
    return location.pathname === path;
  };

  // Handle scroll effect
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 10) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleProfile = () => {
    setIsProfileOpen(!isProfileOpen);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  // Define dashboard link based on user role
  const getDashboardLink = () => {
    if (isAdmin) return '/dashboard/admin';
    if (isTeacher) return '/dashboard/teacher';
    if (isStudent) return '/dashboard/student';
    return '/dashboard';
  };

  const navItemsData = [
    { path: '/', label: 'الرئيسية', icon: <FiHome /> },
    { path: '/courses', label: 'الدورات', icon: <FiBook /> },
    { path: '/about', label: 'من نحن', icon: <FiInfo /> },
    { path: '/contact', label: 'اتصل بنا', icon: <FiMessageSquare /> },
  ];

  return (
    <header className="sticky top-0 z-50">
      <nav className={`w-full z-50 transition-all duration-500 border-b backdrop-blur-sm shadow-sm ${
        isScrolled 
          ? 'bg-white/70 dark:bg-slate-900/70 border-primary/20' 
          : 'bg-transparent dark:bg-transparent border-transparent'
      }`}>
        {/* Scroll Progress Bar */}
        <motion.div 
          className="absolute top-0 left-0 right-0 h-1 origin-left z-50"
          style={{ 
            scaleX,
            backgroundColor: progressColor 
          }}
        />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 md:h-20 items-center">
            <div className="flex-shrink-0 flex items-center">
              <Link to="/" className="flex items-center gap-2 group">
                <motion.div 
                  whileHover={{ scale: 1.1, rotate: 5 }}
                  whileTap={{ scale: 0.95 }}
                  className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shadow-lg group-hover:shadow-glow transition-all duration-300"
                >
                  <span className="text-white text-lg font-bold">و</span>
                </motion.div>
                <motion.span 
                  className={`text-xl md:text-2xl font-title font-bold ${
                    isScrolled 
                      ? 'text-primary dark:text-primary-300' 
                      : 'text-primary dark:text-gray-50'
                  }`}
                  whileHover={{ y: -2 }}
                  transition={{ type: "spring", stiffness: 400, damping: 10 }}
                >
                  وسائلك
                </motion.span>
              </Link>
            </div>

            {/* Desktop Menu */}
            <div className="hidden md:flex items-center space-x-1 space-x-reverse">
              <div className="flex space-x-1 space-x-reverse">
                {navItemsData.map((item) => (
                  <Link 
                    key={item.path} 
                    to={item.path}
                    className={`nav-link flex items-center gap-1.5 ${isActive(item.path) ? 'nav-link-active' : ''}`}
                  >
                    <motion.span 
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      className="text-lg"
                    >
                      {item.icon}
                    </motion.span>
                    <span>{item.label}</span>
                  </Link>
                ))}
              </div>

              <div className="mr-8 flex items-center space-x-2 space-x-reverse">
                {/* Theme Toggle */}
                <motion.button
                  whileHover={{ scale: 1.1, rotate: 15 }}
                  whileTap={{ scale: 0.9, rotate: 0 }}
                  onClick={toggleDarkMode}
                  className={`p-2 rounded-full ${isScrolled 
                    ? 'bg-gray-100/80 dark:bg-slate-800/80 text-primary dark:text-primary-300' 
                    : 'bg-white/10 text-white dark:text-gray-50 backdrop-blur-sm'
                  } focus:outline-none transition-colors duration-300 shadow-sm hover:shadow-md`}
                  aria-label="Toggle dark mode"
                >
                  {darkMode ? <FiSun className="h-5 w-5" /> : <FiMoon className="h-5 w-5" />}
                </motion.button>

                {/* Auth Buttons */}
                {isAuthenticated ? (
                  <div className="relative">
                    <motion.button
                      whileHover={{ scale: 1.03 }}
                      whileTap={{ scale: 0.97 }}
                      onClick={toggleProfile}
                      className={`flex items-center gap-2 px-3 py-2 rounded-xl ${isScrolled 
                        ? 'bg-gray-100/80 dark:bg-slate-800/80 text-gray-900 dark:text-gray-50' 
                        : 'bg-white/10 text-white dark:text-gray-50 backdrop-blur-sm'
                      } transition-all duration-300 shadow-sm hover:shadow-md`}
                    >
                      <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white font-semibold">
                        {currentUser?.name ? currentUser.name.charAt(0).toUpperCase() : <FiUser />}
                      </div>
                      <span className="text-sm font-medium">{currentUser?.name}</span>
                    </motion.button>

                    <AnimatePresence>
                      {isProfileOpen && (
                        <motion.div
                          initial={{ opacity: 0, y: 5, scale: 0.95 }}
                          animate={{ opacity: 1, y: 0, scale: 1 }}
                          exit={{ opacity: 0, y: 5, scale: 0.95 }}
                          transition={{ duration: 0.2 }}
                          className="absolute left-0 mt-2 w-56 bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm rounded-xl shadow-xl py-2 z-10 border border-gray-100 dark:border-gray-700"
                        >
                          <div className="px-4 py-3 border-b border-gray-100 dark:border-gray-700">
                            <p className="text-sm font-medium text-gray-900 dark:text-gray-50">{currentUser?.name}</p>
                            <p className="text-xs text-gray-600 dark:text-gray-300 mt-1">{currentUser?.email}</p>
                          </div>
                          <Link
                            to={getDashboardLink()}
                            className="flex items-center gap-2 px-4 py-2.5 text-sm text-gray-900 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-slate-700 w-full text-right"
                            onClick={() => setIsProfileOpen(false)}
                          >
                            <FiUser className="h-4 w-4" />
                            <span>لوحة التحكم</span>
                          </Link>
                          <div className="border-t border-gray-100 dark:border-gray-700 my-1"></div>
                          <button
                            onClick={handleLogout}
                            className="flex items-center gap-2 px-4 py-2.5 text-sm text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 w-full text-right"
                          >
                            <FiLogOut className="h-4 w-4" />
                            <span>تسجيل الخروج</span>
                          </button>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ) : (
                  <div className="flex space-x-2 space-x-reverse">
                    <Button 
                      as={Link} 
                      to="/login" 
                      variant="outline"
                      size="sm"
                      className={isScrolled ? 'hover:shadow-glow' : 'border-white/70 text-white hover:bg-white/10 dark:border-white/70 dark:text-white'}
                    >
                      تسجيل الدخول
                    </Button>
                    <Button 
                      as={Link} 
                      to="/register/student" 
                      variant="accent"
                      size="sm"
                      className="shadow-md text-gray-900 hover:shadow-accent-glow"
                    >
                      التسجيل
                    </Button>
                  </div>
                )}
              </div>
            </div>

            {/* Mobile Menu Button */}
            <div className="flex md:hidden items-center gap-2">
              {/* Theme Toggle */}
              <motion.button
                whileHover={{ scale: 1.1, rotate: 15 }}
                whileTap={{ scale: 0.9, rotate: 0 }}
                onClick={toggleDarkMode}
                className={`p-2 rounded-full ${isScrolled 
                  ? 'bg-gray-100/80 dark:bg-slate-800/80 text-primary dark:text-primary-300' 
                  : 'bg-white/10 text-white dark:text-gray-50 backdrop-blur-sm'
                } focus:outline-none transition-colors duration-300 shadow-sm`}
                aria-label="Toggle dark mode"
              >
                {darkMode ? <FiSun className="h-5 w-5" /> : <FiMoon className="h-5 w-5" />}
              </motion.button>

              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={toggleMenu}
                className={`p-2 rounded-lg ${isScrolled 
                  ? 'text-gray-900 dark:text-gray-50' 
                  : 'text-white dark:text-white'
                } focus:outline-none transition-colors duration-300`}
                aria-expanded={isMenuOpen}
              >
                {isMenuOpen ? <FiX className="h-6 w-6" /> : <FiMenu className="h-6 w-6" />}
              </motion.button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        <AnimatePresence>
          {isMenuOpen && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3, ease: "easeInOut" }}
              className="md:hidden bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm shadow-lg rounded-b-xl overflow-hidden"
            >
              <div className="px-4 py-5 space-y-3 max-h-[calc(100vh-5rem)] overflow-y-auto">
                {navItemsData.map((item) => (
                  <Link 
                    key={item.path}
                    to={item.path}
                    className={`flex items-center gap-3 p-3 rounded-xl text-base font-medium ${
                      isActive(item.path)
                        ? 'bg-primary-50 dark:bg-slate-700 text-primary dark:text-primary-300'
                        : 'text-gray-900 dark:text-gray-50 hover:bg-gray-50 dark:hover:bg-slate-700'
                    }`}
                    onClick={() => setIsMenuOpen(false)}
                  >
                    <motion.div whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }} className="text-xl">
                      {item.icon}
                    </motion.div>
                    <span>{item.label}</span>
                  </Link>
                ))}

                <div className="border-t border-gray-100 dark:border-gray-700 my-2 pt-2">
                  {isAuthenticated ? (
                    <>
                      <div className="flex items-center gap-3 p-3 mb-2">
                        <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center text-white font-semibold">
                          {currentUser?.name ? currentUser.name.charAt(0).toUpperCase() : <FiUser />}
                        </div>
                        <div>
                          <p className="font-medium text-gray-900 dark:text-gray-50">{currentUser?.name}</p>
                          <p className="text-xs text-gray-600 dark:text-gray-300">{currentUser?.email}</p>
                        </div>
                      </div>
                      <Link
                        to={getDashboardLink()}
                        className="flex items-center gap-3 p-3 rounded-xl text-base font-medium text-gray-900 dark:text-gray-50 hover:bg-gray-50 dark:hover:bg-slate-700"
                        onClick={() => setIsMenuOpen(false)}
                      >
                        <FiUser className="text-xl" />
                        <span>لوحة التحكم</span>
                      </Link>
                      <motion.button
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={() => {
                          handleLogout();
                          setIsMenuOpen(false);
                        }}
                        className="w-full flex items-center gap-3 p-3 rounded-xl text-base font-medium text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                      >
                        <FiLogOut className="text-xl" />
                        <span>تسجيل الخروج</span>
                      </motion.button>
                    </>
                  ) : (
                    <div className="grid grid-cols-2 gap-3 mt-4">
                      <Button 
                        as={Link} 
                        to="/login" 
                        variant="outline"
                        className="w-full hover:shadow-glow"
                        onClick={() => setIsMenuOpen(false)}
                      >
                        تسجيل الدخول
                      </Button>
                      <Button 
                        as={Link} 
                        to="/register/student" 
                        variant="accent"
                        className="w-full text-gray-900 hover:shadow-accent-glow"
                        onClick={() => setIsMenuOpen(false)}
                      >
                        التسجيل
                      </Button>
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </nav>
    </header>
  );
};

export default Navbar;
